function validate([s, letter]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 letters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase English letters.';
  if (typeof letter !== 'string' || !/^[a-z]$/.test(letter)) return 'letter is one lowercase English letter.';
  return null;
}

