function percentageLetter(s, letter) {
  let count = 0;
  for (const ch of s) {
    if (ch === letter) {
      count++;
    }
  }
  const scaled = count * 100;
  return Math.floor(scaled / s.length);
}

brute:
function percentageLetter(s, letter) {
  const hits = s.split('').filter(c => c === letter).length;
  // Find the largest whole percent p with p% of the length not exceeding the hits.
  let p = 0;
  while (p < 100 && (p + 1) * s.length <= hits * 100) p++;
  return p;
}

