function generate(rand, size) {
  const alphabet = size === 'large' || rand() < 0.3 ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const pick = () => alphabet[Math.floor(rand() * alphabet.length)];
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 9);
  // Large inputs lean on one letter so the percentage is not always tiny.
  const heavy = pick();
  const s = Array.from({ length: n }, () => (size === 'large' && rand() < 0.4 ? heavy : pick())).join('');
  const letter = rand() < 0.75 ? s[Math.floor(rand() * n)] : 'abcdefghijklmnopqrstuvwxyz'[Math.floor(rand() * 26)];
  return [s, letter];
}
